// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _test(uint256 callValue) internal {
        callValue = bound(callValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= callValue);
        bool ok = true;
        try c.play{value: callValue}() {} catch { ok = false; }
        assertTrue(ok ? callValue == 10 : true);
    }

    function testFuzz_test(uint256 callValue) public {
        _test(callValue);
    }

    receive() external payable {}
}
